/**
 * 侧边栏 = 网站左侧目录树
 *
 * 这里用「手动分区 + autogenerated 子项」混合模式（Radxa / ArmSoM 都在用）：
 *   - 一级分区在这里写死，保证顺序和命名稳定
 *   - 分区内部交给 autogenerated，文件夹里加 md 就自动出现，不用改这个文件
 *
 * 排序规则（三选一，autogenerated 内部）：
 *   1) md 前置数据里写 sidebar_position: 1, 2, 3...
 *   2) 文件名加数字前缀：01-overview.md（数字不显示在标题里）
 *   3) 文件夹加 _category_.json 控制分类名与位置
 *
 * @type {import('@docusaurus/plugin-content-docs').SidebarsConfig}
 */
const sidebars = {
  docsSidebar: [
    // 站点首页 = docs/intro.md
    'intro',

    {
      type: 'category',
      label: 'Products',
      collapsed: false,
      // 点分类标题会跳到 /products（即 products/overview.md）
      link: { type: 'doc', id: 'products/overview' },
      // 该文件夹下所有 md 自动成为子项
      items: [{ type: 'autogenerated', dirName: 'products' }],
    },

    {
      type: 'category',
      label: 'Getting started',
      collapsed: false,
      link: { type: 'doc', id: 'getting-started/overview' },
      items: [{ type: 'autogenerated', dirName: 'getting-started' }],
    },

    {
      type: 'category',
      label: 'Software',
      link: { type: 'doc', id: 'software/overview' },
      items: [{ type: 'autogenerated', dirName: 'software' }],
    },

    {
      type: 'category',
      label: 'Hardware',
      link: { type: 'doc', id: 'hardware/overview' },
      items: [{ type: 'autogenerated', dirName: 'hardware' }],
    },

    {
      type: 'category',
      label: 'Downloads',
      link: { type: 'doc', id: 'downloads/overview' },
      items: [{ type: 'autogenerated', dirName: 'downloads' }],
    },

    {
      type: 'category',
      label: 'FAQ',
      link: { type: 'doc', id: 'faq/overview' },
      items: [{ type: 'autogenerated', dirName: 'faq' }],
    },

    {
      type: 'category',
      label: 'Community & support',
      link: { type: 'doc', id: 'community/overview' },
      items: [{ type: 'autogenerated', dirName: 'community' }],
    },
  ],
};

module.exports = sidebars;
